const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const error = document.getElementById('form-error');
const confirmation = document.getElementById('booking-confirmation');

const today = new Date();
const pad = n => String(n).padStart(2, '0');
dateInput.min = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;

function prettyDate(value) {
  const d = new Date(`${value}T00:00:00`);
  return d.toLocaleDateString(undefined, {month: 'short', day: 'numeric', year: 'numeric'});
}
function prettyTime(value) {
  const [hour, minute] = value.split(':');
  const d = new Date();
  d.setHours(Number(hour), Number(minute));
  return d.toLocaleTimeString([], {hour: 'numeric', minute: '2-digit'});
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.textContent = '';
  confirmation.hidden = true;
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  const data = new FormData(form);
  const chosen = new Date(`${data.get('date')}T00:00:00`);
  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);
  if (chosen < startOfToday) {
    error.textContent = 'Please choose today or a future date.';
    dateInput.focus();
    return;
  }
  const booking = document.createElement('article');
  booking.className = 'booking';
  booking.dataset.testid = 'booking';
  booking.dataset.status = 'active';
  const top = document.createElement('div');
  top.className = 'booking-top';
  const identity = document.createElement('div');
  const name = document.createElement('h3');
  name.className = 'booking-name';
  name.dataset.testid = 'booking-name-display';
  name.textContent = data.get('name');
  const type = document.createElement('div');
  type.className = 'booking-type';
  type.textContent = data.get('type');
  identity.append(name, type);
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'cancel-button';
  cancel.dataset.testid = 'booking-cancel';
  cancel.textContent = 'Cancel';
  top.append(identity, cancel);
  const details = document.createElement('div');
  details.className = 'booking-details';
  const date = document.createElement('span');
  date.textContent = `▣ ${prettyDate(data.get('date'))}`;
  const time = document.createElement('span');
  time.textContent = `◷ ${prettyTime(data.get('time'))}`;
  details.append(date, time);
  booking.append(top, details);
  emptyState.remove();
  list.prepend(booking);
  confirmation.textContent = `Appointment confirmed for ${data.get('name')}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
  cancel.addEventListener('click', () => {
    booking.dataset.status = 'cancelled';
    cancel.remove();
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'Cancelled';
    top.appendChild(label);
  });
});

const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const error = document.getElementById('form-error');
const confirmation = document.getElementById('booking-confirmation');

const today = new Date();
const pad = n => String(n).padStart(2, '0');
const todayValue = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
dateInput.min = todayValue;

function prettyDate(value) {
  const date = new Date(`${value}T00:00:00`);
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
}

function prettyTime(value) {
  const [hour, minute] = value.split(':');
  const date = new Date();
  date.setHours(Number(hour), Number(minute));
  return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.textContent = '';
  confirmation.hidden = true;

  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }

  const nameValue = document.getElementById('booking-name').value.trim();
  const emailValue = document.getElementById('booking-email').value.trim();
  const dateValue = dateInput.value;
  const timeValue = document.getElementById('booking-time').value;
  const typeValue = document.getElementById('booking-type').value;
  const chosen = new Date(`${dateValue}T00:00:00`);
  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);

  if (chosen < startOfToday) {
    error.textContent = 'Please choose today or a future date.';
    dateInput.focus();
    return;
  }

  const booking = document.createElement('article');
  booking.className = 'booking';
  booking.dataset.testid = 'booking';
  booking.dataset.status = 'active';
  const top = document.createElement('div');
  top.className = 'booking-top';
  const identity = document.createElement('div');
  const name = document.createElement('h3');
  name.className = 'booking-name';
  name.dataset.testid = 'booking-name-display';
  name.textContent = nameValue;
  const type = document.createElement('div');
  type.className = 'booking-type';
  type.textContent = typeValue;
  identity.append(name, type);
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'cancel-button';
  cancel.dataset.testid = 'booking-cancel';
  cancel.textContent = 'Cancel';
  top.append(identity, cancel);
  const details = document.createElement('div');
  details.className = 'booking-details';
  const date = document.createElement('span');
  date.textContent = `▣ ${prettyDate(dateValue)}`;
  const time = document.createElement('span');
  time.textContent = `◷ ${prettyTime(timeValue)}`;
  const email = document.createElement('span');
  email.textContent = emailValue;
  details.append(date, time, email);
  booking.append(top, details);
  if (emptyState.isConnected) emptyState.remove();
  list.prepend(booking);
  confirmation.textContent = `Appointment confirmed for ${nameValue}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = todayValue;

  cancel.addEventListener('click', () => {
    booking.dataset.status = 'cancelled';
    cancel.remove();
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'Cancelled';
    top.appendChild(label);
  });
});

